#include <bits/stdc++.h>
using namespace std;

const int MOD_X=998244353;
const int MOD_Y=1000000007;
long long total_input;
int digits_arr[15], base_arr[15], res;

long long get_value(int *arr, int len){
    long long val=0;
    for (int i=1; i<=len; i++)
        val=val*10+arr[i];
    return val;
}

long long get_rank(int *arr, int len){
    long long count=0;
    for (int d=1; d<=*digits_arr; d++){
        for (int i=1; i<=min(len,d); i++){
            for (int j=(i==1?1:0); j<arr[i]; j++){
                long long leftPart=0, rightPart=0;
                for (int p=1; p<i; p++)
                    leftPart=rightPart=leftPart*10+arr[p];
                leftPart=rightPart=leftPart*10+j;
                for (int p=i+1; p<=d; p++)
                    leftPart=leftPart*10, rightPart=rightPart*10+9;
                rightPart=min(rightPart, total_input);
                if (leftPart<=rightPart)
                    count+=rightPart-leftPart+1;
            }
        }
        if (d<=len) ++count;
    }
    return count;
}

int computeF(int *arr, int len){
    return ((-get_value(arr,len)+get_rank(arr,len))%MOD_X+MOD_X)%MOD_X;
}

int diff_vals[15];
int q1_list[1000010], q2_list[1000010];
long long q2_sum_arr[1000010];

void dfs_range(int start, int end, int *q, int v){
    if (start==end){
        for (int i=0; i<=9; i++)
            q[++*q]=(v+1LL*i*diff_vals[start])%MOD_X;
        return;
    }
    for (int i=0; i<=9; i++)
        dfs_range(start+1, end, q, (v+1LL*i*diff_vals[start])%MOD_X);
}

void do_update(int len, int idx, int val){
    int backup[15];
    memcpy(backup, digits_arr, sizeof(digits_arr));
    digits_arr[idx]=val;
    for (int p=idx+1; p<=len; p++) digits_arr[p]=0;
    int baseVal=computeF(digits_arr,len);
    for (int p=idx+1; p<=len; p++){
        digits_arr[p]=1;
        diff_vals[p]=(computeF(digits_arr,len)+MOD_X-baseVal)%MOD_X;
        digits_arr[p]=0;
    }
    if (len-idx==0){
        res=(res+baseVal)%MOD_Y;
        return;
    }
    if (len-idx==1){
        for (int p=0; p<=9; p++)
            res=(res+(baseVal+1LL*p*diff_vals[len])%MOD_X)%MOD_Y;
        return;
    }
    int mid=(len+idx)/2;
    *q1_list=0; *q2_list=0;
    dfs_range(idx+1, mid, q1_list, baseVal);
    dfs_range(mid+1, len, q2_list, 0);
    std::sort(q2_list+1, q2_list+*q2_list+1);
    long long sumQ2=0;
    for (int i=1; i<=*q2_list; i++)
        sumQ2=(sumQ2+q2_list[i])%MOD_Y;
    for (int i=1; i<=*q1_list; i++){
        int p=lower_bound(q2_list+1, q2_list+*q2_list+1, MOD_X - q1_list[i]) - q2_list;
        res=(res+sumQ2+1LL*(*q2_list)*q1_list[i])%MOD_Y;
        res=(res+1LL*((*q2_list)-p+1)*(MOD_Y-MOD_X))%MOD_Y;
    }
}

int main(){
    scanf("%lld", &total_input);
    long long m=total_input;
    for (*digits_arr=0; m; m/=10) digits_arr[++*digits_arr]=m%10;
    std::reverse(digits_arr+1, digits_arr+*digits_arr+1);
    for (int d=1; d<=*digits_arr; d++){
        for (int i=1; i<=d; i++){
            int l=(i==1?1:0);
            int r=(d==*digits_arr?digits_arr[i]-1:9);
            for (int j=l; j<=r; j++)
                if (j!=digits_arr[i]) do_update(d, i, j);
        }
        res=(res+computeF(digits_arr, d))%MOD_Y;
    }
    printf("%d\n", res);
}
